}
baj:clean () 
{ 
    local ns=${FUNCNAME%%:*};
    local i;
    for i in ${BASH_ALIASES[@]/$ns:clean};
    do
        if [[ $i =~ ${1:?}: ]]; then
            unalias "${i/$ns:}";
        fi;
    done;
    for i in $(compgen -c $1);
    do
        unset $i;
    done
}
