bajl:args () 
{ 
    mapfile -t;
    ((${#MAPFILE[@]} > 0)) && "${@:-echo}" "${MAPFILE[@]}"
}
bajl:as-cmd () 
{ 
    bajl:as-lib "$@";
    echo 'eval "$@"'
}
bajl:as-lib () 
{ 
    bajl:warn;
