}
bajl:load () 
{ 
    bajl:forget $(nss "$@");
    . <(${FUNCNAME%%:*}:txt "$@")
}
bajl:loop () 
{ 
    local i;
    for i in "${@:2}";
    do
        $1 "$i";
    done
}
bajl:map () 
{ 
    while read; do
        "${@:-echo}" "$REPLY";
    done
}
