bajl:opts () 
{ 
    local opt val tmp i;
    args=();
    until [[ $# -eq 0 ]]; do
        case "$1" in 
            --)
                shift;
                break
            ;;
            --*=*)
                opt="${1%%=*}";
                val="${1#*=}";
                opts["${opt:2}"]="$val";
                shift
            ;;
            --*)
                opts["${1:2}"]="1";
                shift
            ;;
            -[0-9]*)
                args+=("$1");
                shift
            ;;
            -)
                args+=("$1");
                shift
            ;;
            -*)
                tmp=${1:1};
                for ((i = 0; i < ${#tmp}; i++ ))
                do
                    opt="${tmp:$i:1}";
                    opts[$opt]=$((opts[$opt] + 1));
                done;
                shift
            ;;
            *)
                args+=("$1");
                shift
            ;;
        esac;
    done;
    cont=("$@")
}
bajl:prudent () 
{ 
    echo set -euo pipefail;
    echo shopt -s inherit_errexit
}
