bajl:tst () 
{ 
    < ${1:?}
}
bajl:txt () 
{ 
    bajl:loop bajl:tst "$@" && cat "$@" | bajl:txt1
}
bajl:txt1 () 
{ 
    baj:header;
    baj:asjs | baj:bm4 | baj:dist | baj:emit
}
bajl:warn () 
{ 
    echo \# generated by ${FUNCNAME[1]}, avoid edit
}
bajl:with-lib () 
{ 
    (($#)) || bajl:fail;
    bajl:optal;
    until [[ $# == 0 || $1 == -- ]]; do
        bajl:lib1 $1;
        shift;
    done;
    [[ $1 == -- ]] && shift;
    bajl:def self;
    (($#)) && { 
        f=${BASH_ALIASES[$1]:-$1};
        shift;
        echo $f "${@@Q}"
    }
}
bajl:yml2sh () 
{ 
    bajl:load ${1:?};
    bajl:nss1 $1 | bajl:args bajl:as-cmd
}
ns:bajl () 
{ 
    bajl:${1:?} "${@:2}"
}
bajl:self () 
{ 
    jq "$jq" "$@"
}
